with deduped as (select id, order_id, shipped_date, delivered_date, cost, status from (select *, row_number() over (partition by carrier order by shipped_date, id) as dedup_rank from shipments) ranked where dedup_rank = 1) select date_trunc('week', shipped_date) as week_start, stddev_samp(cost) as cost_stddev, round(avg(cost), 2) as avg_cost, sum(case when status = 'IN_TRANSIT' then cost else 0 end) as in_transit_cost, sort_array(collect_set(status)) as status_list, stddev_samp(cost) as cost_stddev_2 from deduped group by date_trunc('week', shipped_date);
